import { HttpError } from './http.ts';

const WEIGHTS = [8, 6, 4, 2, 3, 5, 9, 7];

/** UPU S10 check digit for 8 serial digits (algorithm: docs/carriers.md). */
export function s10CheckDigit(serial: string): number {
  const sum = WEIGHTS.reduce((acc, weight, i) => acc + weight * Number(serial[i]), 0);
  const result = 11 - (sum % 11);
  if (result === 10) return 0;
  if (result === 11) return 5;
  return result;
}

/**
 * Validates an Austrian Post (ATP) tracking number: 2 letters, 8 digits, 1 check digit, `AT`.
 * Expects the already upper-cased number. Error messages are shown to the packers, hence German.
 */
export function assertValidAtpTrackingNumber(trackingNumber: string): void {
  const match = /^[A-Z]{2}(\d{8})(\d)AT$/.exec(trackingNumber);
  if (!match) {
    throw new HttpError(
      400,
      'INVALID_TRACKING_NUMBER',
      `Ungültige Sendungsnummer für ATP: erwartet werden 2 Buchstaben, 8 Ziffern, 1 Prüfziffer und „AT“ (z. B. RR123456785AT)`,
    );
  }
  const expected = s10CheckDigit(match[1]);
  if (Number(match[2]) !== expected) {
    throw new HttpError(
      400,
      'INVALID_TRACKING_NUMBER',
      `Ungültige Prüfziffer der Sendungsnummer ${trackingNumber}: erwartet wird ${expected}`,
    );
  }
}
